{
  "IP": "neorv32_hwspinlock",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Lock ownership state",
      "Unit": "neorv32_hwspinlock",
      "Information": "The 32 lock ownership bits held by the unit determine which spinlocks are asserted or released, and the lock state is returned to bus readers. The state is internal until it is exposed through the lock-status readback.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because a bus write changes the selected lock bit at line 45 under the access conditions at line 44. Availability is at risk because writes can leave lock bits asserted at line 45, preventing clients from acquiring required locks.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker issues writes that assert selected lock bits and thereby corrupts lock ownership or keeps required locks unavailable.",
      "Enters Through": [],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [],
      "Held Lines": [
        42,
        45
      ],
      "Exit Lines": [
        68,
        70
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Lock-entry selection",
      "Unit": "neorv32_hwspinlock",
      "Information": "The address-derived selection determines which lock entry is updated or which entry contributes to a read response. The selector is generated internally and is not itself returned as a bus value.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because line 51 derives the selection from the request address, and line 44 uses it to choose which lock state can change. Availability is at risk because a faulty or manipulated selection can steer an access away from the required lock, while line 68 uses it to determine which lock data is returned.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker supplies a crafted address so an access targets a different lock entry, leaving the intended lock unchanged or returning the wrong lock status.",
      "Enters Through": [],
      "Leaves Through": [],
      "Entry Lines": [],
      "Held Lines": [
        51
      ],
      "Exit Lines": []
    }
  ],
